  all_bytes pl -> 0 <= size -> 0 <= rw <= 4095 ->
  fse_fill fuel pl size s maxSV rw acc = (pre, rw', size') ->
  exists ds, harness_fill fuel ds s maxSV rw acc = Some (pre, rw', []).
