Theorem fseB_tail_spec pl rem dsz bsz :
  all_bytes pl -> 0 <= rem -> dsz <= bsz ->
  let '(junk, rem') := fseB_tail pl rem dsz bsz in
  Zlength junk = bsz - dsz /\ all_bytes junk /\ 0 <= rem' <= rem.
