(* [comment removed for export] *)
Theorem fseA_valid_stream pl n junk :
  all_bytes pl -> 0 <= n ->
  let '(tl, msv, nc, data, dsz, bsz, rem) := fseA pl n in
  all_bytes junk -> valid_stream nc msv tl (data ++ junk).
